import 'react-native-gesture-handler';
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { NavigationContainer } from "@react-navigation/native";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import { createStackNavigator } from "@react-navigation/stack";
import { StatusBar } from "expo-status-bar";
import { Ionicons } from "@expo/vector-icons";
import { View, StyleSheet } from "react-native";
import { LinearGradient } from "expo-linear-gradient";
import { SafeAreaProvider, useSafeAreaInsets } from "react-native-safe-area-context";

import ScannerScreen from "./src/screens/ScannerScreen";
import ChallanScreen from "./src/screens/ChallanScreen";
import ChallanManagementScreen from "./src/screens/ChallanManagementScreen";
import LoginScreen from "./src/screens/LoginScreen";
import AdminUsersScreen from "./src/screens/AdminUsersScreen";
import ProfileScreen from "./src/screens/ProfileScreen";
import SplashScreen from "./src/screens/SplashScreen";
import LogsScreen from "./src/screens/LogsScreen";
import InquiriesScreen from "./src/screens/InquiriesScreen";
import PowerScreen from "./src/screens/PowerScreen";
import ProductionScreen from "./src/screens/ProductionScreen";
import ProductionOutputScreen from "./src/screens/ProductionOutputScreen";
import ReportsScreen from "./src/screens/ReportsScreen";
import PurchasesScreen from "./src/screens/PurchasesScreen";
import TabGroupScreen from "./src/components/TabGroupScreen";
import ErrorBoundary from "./src/components/ErrorBoundary";

import { ChallanProvider } from "./src/context/ChallanContext";
import { AuthProvider, useAuth } from "./src/context/AuthContext";
import { RefreshBusProvider } from "./src/context/RefreshBusContext";
import { colors } from "./src/theme/colors";
import { radii } from "./src/theme/radii";
import { spacingSizes, textSizes, shadows, sizes } from "./src/theme/responsive";
import { trackAppOpen } from "./src/services/analyticsService";
import { TAB_KEYS, GROUP_KEYS, getVisibleGroupsForRoles } from "./src/config/roleTabs";
import { supabase } from "./src/config/supabase";

const Tab = createBottomTabNavigator();
const Stack = createStackNavigator();

// Map of TAB_KEY → Screen component
const SCREEN_MAP = {
  [TAB_KEYS.SCANNER]: ScannerScreen,
  [TAB_KEYS.CHALLAN]: ChallanScreen,
  [TAB_KEYS.CHALLAN_MANAGEMENT]: ChallanManagementScreen,
  [TAB_KEYS.USERS]: AdminUsersScreen,
  [TAB_KEYS.LOGS]: LogsScreen,
  [TAB_KEYS.INQUIRIES]: InquiriesScreen,
  [TAB_KEYS.POWER]: PowerScreen,
  [TAB_KEYS.PRODUCTION]: ProductionScreen,
  [TAB_KEYS.PRODUCTION_OUTPUT]: ProductionOutputScreen,
  [TAB_KEYS.PURCHASES]: PurchasesScreen,
  [TAB_KEYS.REPORTS]: ReportsScreen,
  [TAB_KEYS.PROFILE]: ProfileScreen,
};

// Custom Tab Bar Button with gradient for active state
const TabBarIcon = ({ focused, iconName, color }) => {
  if (focused) {
    return (
      <View style={styles.tabIconContainerActive}>
        <LinearGradient
          colors={[colors.primary[50], colors.primary[100]]}
          style={styles.tabIconGradient}
        >
          <Ionicons name={iconName} size={22} color={colors.primary[600]} />
        </LinearGradient>
      </View>
    );
  }

  return (
    <View style={styles.tabIconContainer}>
      <Ionicons name={iconName} size={22} color={color} />
    </View>
  );
};

function MainTabNavigator() {
  const { roles } = useAuth();
  const insets = useSafeAreaInsets();
  const isAdmin = roles?.includes('admin');
  const [pendingInquiries, setPendingInquiries] = useState(0);

  const fetchPendingInquiries = useCallback(async () => {
    if (!isAdmin) {
      setPendingInquiries(0);
      return;
    }
    const { count, error } = await supabase
      .from('website_inquiries')
      .select('id', { count: 'exact', head: true })
      .eq('status', 'new');
    if (!error) {
      setPendingInquiries(count || 0);
    }
  }, [isAdmin]);

  useEffect(() => {
    fetchPendingInquiries();
    if (!isAdmin) return;

    const channel = supabase
      .channel('inquiries-badge')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'website_inquiries' },
        () => {
          fetchPendingInquiries();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [fetchPendingInquiries, isAdmin]);

  const visibleGroups = useMemo(() => getVisibleGroupsForRoles(roles), [roles]);

  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        tabBarIcon: ({ focused, color }) => {
          const group = visibleGroups.find((g) => g.key === route.name);
          const iconName = focused ? group?.icon : group?.iconOutline;
          return <TabBarIcon focused={focused} iconName={iconName || 'ellipse'} color={color} />;
        },
        tabBarActiveTintColor: colors.primary[600],
        tabBarInactiveTintColor: colors.neutral[400],
        tabBarStyle: {
          backgroundColor: colors.white,
          borderTopWidth: 0,
          height: sizes.tabBarBase + Math.max(insets.bottom, spacingSizes.sm),
          paddingBottom: Math.max(insets.bottom, spacingSizes.sm),
          paddingTop: spacingSizes.sm,
          ...shadows.medium,
          position: 'absolute',
          left: 0,
          right: 0,
          bottom: 0,
          borderTopLeftRadius: radii.xxl,
          borderTopRightRadius: radii.xxl,
        },
        tabBarLabelStyle: {
          fontSize: textSizes.tiny,
          fontWeight: "600",
          marginTop: 4,
        },
        tabBarItemStyle: {
          paddingTop: 4,
        },
        headerShown: false,
      })}
    >
      {visibleGroups.map((group) => {
        // Check if management group has inquiries for badge
        const showBadge =
          group.key === GROUP_KEYS.INQUIRIES &&
          pendingInquiries > 0;

        return (
          <Tab.Screen
            key={group.key}
            name={group.key}
            options={{
              tabBarLabel: group.label,
              tabBarBadge: showBadge ? pendingInquiries : undefined,
              tabBarBadgeStyle: {
                backgroundColor: colors.error[500],
                color: colors.white,
                fontSize: textSizes.tiny,
                fontWeight: "700",
              },
            }}
          >
            {() => (
              <TabGroupScreen
                subTabs={group.subTabs}
                screens={SCREEN_MAP}
              />
            )}
          </Tab.Screen>
        );
      })}
    </Tab.Navigator>
  );
}


function RootNavigator() {
  const { user, loading } = useAuth();

  if (loading) {
    return <SplashScreen />;
  }

  return (
    <Stack.Navigator
      screenOptions={{
        headerShown: false,
        animation: 'fade',
        animationDuration: 200,
      }}
    >
      {!user ? (
        <Stack.Screen
          name="Login"
          component={LoginScreen}
          options={{
            animationTypeForReplace: 'pop',
          }}
        />
      ) : (
        <Stack.Screen
          name="MainApp"
          component={MainTabNavigator}
        />
      )}
    </Stack.Navigator>
  );
}

export default function App() {
  useEffect(() => {
    trackAppOpen();
  }, []);

  return (
    <ErrorBoundary>
      <SafeAreaProvider>
        <RefreshBusProvider>
          <AuthProvider>
            <ChallanProvider>
              <NavigationContainer>
                <StatusBar style="dark" />
                <RootNavigator />
              </NavigationContainer>
            </ChallanProvider>
          </AuthProvider>
        </RefreshBusProvider>
      </SafeAreaProvider>
    </ErrorBoundary>
  );
}

const styles = StyleSheet.create({
  tabIconContainer: {
    width: 44,
    height: 44,
    borderRadius: 14,
    justifyContent: 'center',
    alignItems: 'center',
  },
  tabIconContainerActive: {
    width: 44,
    height: 44,
    borderRadius: 14,
    overflow: 'hidden',
  },
  tabIconGradient: {
    flex: 1,
    width: '100%',
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 14,
  },
});
