  const insightCards = useMemo(() => {
    if (!reportData) return [];
    try {
    const insights = [];

    const pt = productionTotals;
    const dayS = reportData?.production?.dayShiftTotals;
    const nightS = reportData?.production?.nightShiftTotals;



    // 2. Most Used Raw Material
    if (rawMaterialTotals.length > 0) {
      const sorted = [...rawMaterialTotals].sort((a, b) => toNumber(b.quantity) - toNumber(a.quantity));
      const top = sorted[0];
      insights.push({
        question: 'Most Used Raw Material?',
        answer: top?.name || 'N/A',
        detail: top ? `${formatWeight(top.quantity)} consumed` : '',
        icon: 'cube',
        color: '#EF4444',
        type: 'highlight',
      });
    }

    // 3. Day vs Night Shift
    if (dayS && nightS) {
      const dayTotal = toNumber(dayS.stretch?.units) + toNumber(dayS.bubble?.units) + toNumber(dayS.baby?.units) + toNumber(dayS.pouch?.pieces);
      const nightTotal = toNumber(nightS.stretch?.units) + toNumber(nightS.bubble?.units) + toNumber(nightS.baby?.units) + toNumber(nightS.pouch?.pieces);
      const total = dayTotal + nightTotal;
      const dayPct = total > 0 ? Math.round((dayTotal / total) * 100) : 0;
      const nightPct = total > 0 ? 100 - dayPct : 0;
      const winner = dayTotal >= nightTotal ? 'Day Shift' : 'Night Shift';
      insights.push({
        question: 'Which Shift is More Efficient?',
        answer: winner,
        detail: `${dayPct}% Day · ${nightPct}% Night`,
        icon: dayTotal >= nightTotal ? 'sunny-outline' : 'moon-outline',
        color: dayTotal >= nightTotal ? '#F59E0B' : '#6366F1',
        type: 'highlight',
      });
    }

    // 4. Day vs Night — weight comparison
    if (dayS && nightS) {
      const dayWeight = toNumber(dayS.stretch?.weight) + toNumber(dayS.bubble?.weight);
      const nightWeight = toNumber(nightS.stretch?.weight) + toNumber(nightS.bubble?.weight);
      insights.push({
        question: 'Day vs Night — Production Weight?',
        answer: `Day: ${formatWeight(dayWeight)}`,
        detail: `Night: ${formatWeight(nightWeight)}`,
        icon: 'scale-outline',
        color: '#10B981',
        type: 'comparison',
      });
    }

    // 5. Best Production Day
    if (productionDaily.length > 1) {
      let bestDay = null;
      let bestOutput = 0;
      productionDaily.forEach((day) => {
        const output = toNumber(day.totals.stretch?.units) + toNumber(day.totals.bubble?.units) +
          toNumber(day.totals.baby?.units) + toNumber(day.totals.pouch?.pieces);
        if (output > bestOutput) {
          bestOutput = output;
          bestDay = day.date;
        }
      });
      insights.push({
        question: 'Best Production Day?',
        answer: bestDay ? formatDateLabel(bestDay) : 'N/A',
        detail: bestDay ? `${formatNumber(bestOutput)} total units/pieces` : '',
        icon: 'calendar',
        color: '#6366F1',
        type: 'highlight',
      });
    }

    // 6. Total Production Weight
    if (pt) {
      const totalWeight = toNumber(pt.stretch?.weight) + toNumber(pt.bubble?.weight);
      insights.push({
        question: 'Total Production Weight?',
        answer: formatWeight(totalWeight),
        detail: `Stretch: ${formatWeight(pt.stretch?.weight)} · Bubble: ${formatWeight(pt.bubble?.weight)}`,
        icon: 'barbell-outline',
        color: '#8B5CF6',
        type: 'stat',
      });
    }

    // 7. Busiest Sales Day
    if (salesDaily.length > 1) {
      let bestSalesDay = null;
      let bestWeight = 0;
      salesDaily.forEach((day) => {
        const w = toNumber(day.grossWeight);
        if (w > bestWeight) {
          bestWeight = w;
          bestSalesDay = day.date;
        }
      });
      insights.push({
        question: 'Busiest Sales Day?',
        answer: bestSalesDay ? formatDateLabel(bestSalesDay) : 'N/A',
        detail: bestSalesDay ? `${formatWeight(bestWeight)} dispatched` : '',
        icon: 'rocket-outline',
        color: '#06B6D4',
        type: 'highlight',
      });
    }



    return insights;
    } catch (e) {
      console.error('insightCards error', e);
      return [];
    }
  }, [reportData, productionTotals, rawMaterialTotals, productionDaily, salesDaily]);

