import React, { useState, useRef, useEffect, useCallback, useContext, useMemo } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated } from 'react-native';
import { useIsFocused } from '@react-navigation/native';
import { Ionicons } from '@expo/vector-icons';
import { colors } from '../theme/colors';
import { radii } from '../theme/radii';
import { spacingSizes, textSizes, iconSizes } from '../theme/responsive';
import { useResponsiveLayout } from '../hooks/useResponsiveLayout';
import { SUB_TAB_META } from '../config/roleTabs';
import ErrorBoundary from './ErrorBoundary';

// Lets child screens switch the active sub-tab within their group (e.g. Scanner
// → "Challans"). Screens rendered outside a group get the safe no-op default.
// `hasSegmentBar` tells ScreenHeader whether the segment bar above it already
// consumed the top safe-area inset.
export const TabGroupContext = React.createContext({
  activeTab: null,
  navigateToTab: () => {},
  hasSegmentBar: false,
});
export const useTabGroup = () => useContext(TabGroupContext);

export default function TabGroupScreen({ subTabs, screens }) {
  const [activeTab, setActiveTab] = useState(subTabs[0]);
  const [refreshTick, setRefreshTick] = useState(0);
  const slideAnim = useRef(new Animated.Value(0)).current;
  const isFocused = useIsFocused();
  const { width, contentMaxWidth, insets } = useResponsiveLayout();

  // NOTE: all hooks must run unconditionally (the single-sub-tab early return
  // lives below them) — sub-tab counts can change at runtime when roles change.
  const tabCount = subTabs.length;
  const activeIndex = subTabs.indexOf(activeTab);
  const segmentAreaWidth = Math.min(width, contentMaxWidth);
  const segmentWidth = (segmentAreaWidth - spacingSizes.lg * 2 - 8) / tabCount;

  useEffect(() => {
    Animated.spring(slideAnim, {
      toValue: activeIndex * segmentWidth,
      useNativeDriver: true,
      tension: 68,
      friction: 12,
    }).start();
  }, [activeIndex, segmentWidth, slideAnim]);

  useEffect(() => {
    if (isFocused) {
      setRefreshTick((tick) => tick + 1);
    }
  }, [isFocused]);

  const handleTabPress = useCallback((tabKey) => {
    setActiveTab(tabKey);
    setRefreshTick((tick) => tick + 1);
  }, []);

  const navigateToTab = useCallback((tabKey) => {
    if (subTabs.includes(tabKey)) handleTabPress(tabKey);
  }, [subTabs, handleTabPress]);

  const tabGroupValue = useMemo(
    () => ({ activeTab, navigateToTab, hasSegmentBar: tabCount > 1 }),
    [activeTab, navigateToTab, tabCount]
  );

  // If only one sub-tab, render the screen directly (no segment control)
  if (tabCount === 1) {
    const ScreenComponent = screens[subTabs[0]];
    if (!ScreenComponent) return null;
    return (
      <TabGroupContext.Provider value={tabGroupValue}>
        <ErrorBoundary><ScreenComponent /></ErrorBoundary>
      </TabGroupContext.Provider>
    );
  }

  const ActiveScreen = screens[activeTab];

  return (
    <TabGroupContext.Provider value={tabGroupValue}>
    <View style={styles.container}>
      {/* Segment Control */}
      <View style={[styles.segmentWrapper, { paddingTop: insets.top + spacingSizes.sm }]}>
        <View style={[styles.segmentContainer, { width: segmentAreaWidth - spacingSizes.lg * 2 }]}>
          {/* Animated active indicator */}
          <Animated.View
            style={[
              styles.activeIndicator,
              {
                width: segmentWidth,
                transform: [{ translateX: slideAnim }],
              },
            ]}
          />

          {subTabs.map((tabKey) => {
            const meta = SUB_TAB_META[tabKey] || { label: tabKey, icon: 'ellipse-outline' };
            const isActive = activeTab === tabKey;

            return (
              <TouchableOpacity
                key={tabKey}
                style={[styles.segmentTab, { width: segmentWidth }]}
                onPress={() => handleTabPress(tabKey)}
                activeOpacity={0.7}
                accessibilityRole="tab"
                accessibilityState={{ selected: isActive }}
                accessibilityLabel={meta.label}
              >
                <Ionicons
                  name={meta.icon}
                  size={iconSizes.sm}
                  color={isActive ? colors.white : colors.neutral[500]}
                />
                <Text
                  style={[styles.segmentLabel, isActive && styles.segmentLabelActive]}
                  numberOfLines={1}
                >
                  {meta.label}
                </Text>
              </TouchableOpacity>
            );
          })}
        </View>
      </View>

      {/* Active screen content */}
      <View style={styles.screenContainer}>
        {ActiveScreen ? (
          <ErrorBoundary>
            <ActiveScreen refreshSignal={refreshTick} activeTabKey={activeTab} />
          </ErrorBoundary>
        ) : null}
      </View>
    </View>
    </TabGroupContext.Provider>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.neutral[100],
  },
  segmentWrapper: {
    backgroundColor: colors.white,
    paddingHorizontal: spacingSizes.lg,
    paddingBottom: spacingSizes.sm,
    borderBottomWidth: 1,
    borderBottomColor: colors.neutral[100],
    alignItems: 'center',
  },
  segmentContainer: {
    flexDirection: 'row',
    backgroundColor: colors.neutral[100],
    borderRadius: radii.md,
    padding: 4,
    position: 'relative',
  },
  activeIndicator: {
    position: 'absolute',
    top: 4,
    left: 4,
    bottom: 4,
    borderRadius: radii.sm,
    backgroundColor: colors.primary[600],
    zIndex: 0,
  },
  segmentTab: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: spacingSizes.sm + 2,
    gap: 5,
    zIndex: 1,
  },
  segmentLabel: {
    fontSize: textSizes.small,
    fontWeight: '600',
    color: colors.neutral[500],
  },
  segmentLabelActive: {
    color: colors.white,
    fontWeight: '700',
  },
  screenContainer: {
    flex: 1,
  },
});
